package com.procurement.vendorquotation.specification;import com.procurement.vendorquotation.entity.*;import org.springframework.data.jpa.domain.Specification;public final class VendorQuotationSpecification{private VendorQuotationSpecification(){}public static Specification<VendorQuotation>search(String keyword,Long rfqId,Long vendorId,VendorQuotationStatus status){return(r,q,b)->{var p=b.conjunction();if(keyword!=null&&!keyword.isBlank())p=b.and(p,b.like(b.lower(r.get("quotationNumber")),"%"+keyword.toLowerCase()+"%"));if(rfqId!=null)p=b.and(p,b.equal(r.get("rfq").get("id"),rfqId));if(vendorId!=null)p=b.and(p,b.equal(r.get("vendor").get("id"),vendorId));if(status!=null)p=b.and(p,b.equal(r.get("status"),status));return p;};}}
